questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
cosd(x) := float(cos(x*%pi/180)); sind(x) := float(sin(x*%pi/180));
atand(x) := float(180*atan(x)/%pi); asind(x) := float(180*asin(x)/%pi);
r1(x) := float(floor(10*x+1/2)/10);
clr(x, L) := every(lambda([y], is(abs(x-y)>0.2)), L);
/* Design: steering to make good a required direction, with bearings. Generic-wrong offsets change sign on a variant where +offset lands near a diagnostic. Source: adapted from SMP AS/A2 Mechanics 1, chapter 2, section F, F4 and Example 8. */
Tk: 20*rand(18);
v: rand([8,12,14,16,18,20]);
u: rand_with_step(2,5,1);
rel: rand([35,55,125,145])*rand([1,-1]);
k: mod(Tk+rel,360);
dd: asind(u*sind(rel)/v);
cs: mod(Tk-dd,360);
gs: v*cosd(dd)+u*cosd(rel);
ad: abs(dd);
/* diagnostics */
cw: mod(Tk+dd,360);
cp: mod(Tk-signum(rel)*asind(u/v),360);
gv: v; gp: sqrt(v^2-u^2); gd: v-u; gsu: v+u;
o1: if clr(r1(cs)+5,[cw,cp]) then 1 else -1;
o2: if clr(r1(gs)+1.5,[gv,gp,gd,gsu]) then 1 else -1;

feedbackvariables.text:
yo: mod(ans1-Tk+180,360)-180;
yx: v*sind(abs(yo));
ysame: is(yo*rel>0);
